// text.hpp — small text utilities: trimming, case-insensitive matching,
// number parsing and the CSV encoding used by the data files.
#pragma once

#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace crm {

// Remove spaces, tabs and carriage returns at both ends.
std::string trim(std::string_view s);

// ASCII lower-case copy (bytes >= 128, e.g. UTF-8 accented letters, are kept as they are).
std::string to_lower(std::string_view s);

// Case-insensitive substring test; an empty needle matches everything.
bool contains_ci(std::string_view haystack, std::string_view needle);

// True if the text contains a control character (line break, tab, ...).
bool has_control_chars(std::string_view s);

// The whole (trimmed) text must be an integer in [lo, hi].
std::optional<long long> parse_int(std::string_view text, long long lo, long long hi);

// Money in euros with at most two decimals ("480", "480.5", "480,50") -> cents.
std::optional<std::int64_t> parse_money(std::string_view text);

// Cents -> "480.50".
std::string format_money(std::int64_t cents);

// CSV (RFC 4180): quote a field if it contains a comma, a quote or a line break.
std::string csv_escape(std::string_view field);
std::string csv_join(const std::vector<std::string>& fields);
// Split one line into fields; false if a quoted field is not terminated.
bool csv_split(std::string_view line, std::vector<std::string>& fields);

}  // namespace crm
```

```{.cpp filename="src/text.cpp"}
// text.cpp — implementation of the text utilities.
#include "crm/text.hpp"

#include <charconv>
#include <limits>

namespace crm {

std::string trim(std::string_view s) {
    const auto first = s.find_first_not_of(" \t\r\n");
    if (first == std::string_view::npos) return {};
    const auto last = s.find_last_not_of(" \t\r\n");
    return std::string(s.substr(first, last - first + 1));
}

std::string to_lower(std::string_view s) {
    std::string out(s);
    for (char& c : out)
        if (c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a');
    return out;
}

bool contains_ci(std::string_view haystack, std::string_view needle) {
    return to_lower(haystack).find(to_lower(needle)) != std::string::npos;
}

bool has_control_chars(std::string_view s) {
    for (unsigned char c : s)
        if (c < 32 || c == 127) return true;
    return false;
}

std::optional<long long> parse_int(std::string_view text, long long lo, long long hi) {
    const std::string t = trim(text);
    if (t.empty()) return std::nullopt;
    long long value = 0;
    const auto [ptr, ec] = std::from_chars(t.data(), t.data() + t.size(), value);
    if (ec != std::errc{} || ptr != t.data() + t.size()) return std::nullopt;
    if (value < lo || value > hi) return std::nullopt;
    return value;
}

std::optional<std::int64_t> parse_money(std::string_view text) {
    const std::string t = trim(text);
    const auto sep = t.find_first_of(".,");
    const std::string whole = t.substr(0, sep);
    const std::string frac = sep == std::string::npos ? "" : t.substr(sep + 1);
    if (whole.empty() || frac.size() > 2) return std::nullopt;
    for (char c : whole + frac)
        if (c < '0' || c > '9') return std::nullopt;            // also rejects a sign
    constexpr std::int64_t max_euros = 1'000'000'000;          // a sanity limit, far from overflow
    const auto euros = parse_int(whole, 0, max_euros);
    if (!euros) return std::nullopt;
    std::int64_t cents = 0;
    if (frac.size() == 1) cents = (frac[0] - '0') * 10;
    if (frac.size() == 2) cents = (frac[0] - '0') * 10 + (frac[1] - '0');
    return *euros * 100 + cents;
}

std::string format_money(std::int64_t cents) {
    const std::int64_t euros = cents / 100, rest = cents % 100;
    return std::to_string(euros) + '.' + (rest < 10 ? "0" : "") + std::to_string(rest);
}

std::string csv_escape(std::string_view field) {
    if (field.find_first_of(",\"\r\n") == std::string_view::npos) return std::string(field);
    std::string out = "\"";
    for (char c : field) {
        if (c == '"') out += '"';                // a quote is written twice
        out += c;
    }
    out += '"';
    return out;
}

std::string csv_join(const std::vector<std::string>& fields) {
    std::string line;
    for (std::size_t i = 0; i < fields.size(); ++i) {
        if (i > 0) line += ',';
        line += csv_escape(fields[i]);
    }
    return line;
}

bool csv_split(std::string_view line, std::vector<std::string>& fields) {
    if (!line.empty() && line.back() == '\r') line.remove_suffix(1);   // files edited on Windows
    fields.assign(1, "");
    bool quoted = false;
    for (std::size_t i = 0; i < line.size(); ++i) {
        const char c = line[i];
        if (quoted) {
            if (c == '"' && i + 1 < line.size() && line[i + 1] == '"') {
                fields.back() += '"';
                ++i;
            } else if (c == '"') {
                quoted = false;                  // closing quote
            } else {
                fields.back() += c;
            }
        } else if (c == '"' && fields.back().empty()) {
            quoted = true;                       // opening quote at the start of a field
        } else if (c == ',') {
            fields.emplace_back();
        } else {
            fields.back() += c;
        }
    }
    return !quoted;
}

}  // namespace crm
```

```{.cpp filename="include/crm/date.hpp"}
// date.hpp — calendar dates and times of day, always valid once constructed.
#pragma once

#include <compare>
#include <optional>
#include <string>
#include <string_view>

namespace crm {

class Date {
public:
    // Parse "YYYY-MM-DD" (years 1900-2200); std::nullopt if the text is not a valid date.
    static std::optional<Date> parse(std::string_view text);
    static bool is_leap(int year);
    static int days_in_month(int year, int month);

    int year() const { return year_; }
    int month() const { return month_; }
    int day() const { return day_; }
    std::string str() const;                                       // "YYYY-MM-DD"
    friend auto operator<=>(const Date&, const Date&) = default;    // chronological order

private:
    Date(int y, int m, int d) : year_(y), month_(m), day_(d) {}
    int year_, month_, day_;                                       // declaration order = comparison order
};

class TimeOfDay {
public:
    static std::optional<TimeOfDay> parse(std::string_view text);   // "HH:MM", 00:00-23:59
    std::string str() const;
    friend auto operator<=>(const TimeOfDay&, const TimeOfDay&) = default;

private:
    explicit TimeOfDay(int minutes) : minutes_(minutes) {}
    int minutes_;                                                  // minutes since midnight
};

}  // namespace crm
```

```{.cpp filename="src/date.cpp"}
// date.cpp — parsing and formatting of dates and times.
#include "crm/date.hpp"

#include <cstdio>

#include "crm/text.hpp"

namespace crm {

bool Date::is_leap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;   // Gregorian rule
}

int Date::days_in_month(int year, int month) {
    static constexpr int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    return month == 2 && is_leap(year) ? 29 : days[month - 1];
}

std::optional<Date> Date::parse(std::string_view text) {
    const std::string t = trim(text);
    if (t.size() != 10 || t[4] != '-' || t[7] != '-') return std::nullopt;
    const auto y = parse_int(t.substr(0, 4), 1900, 2200);
    const auto m = parse_int(t.substr(5, 2), 1, 12);
    if (!y || !m) return std::nullopt;
    const auto d = parse_int(t.substr(8, 2), 1, days_in_month(int(*y), int(*m)));
    if (!d) return std::nullopt;
    return Date(int(*y), int(*m), int(*d));
}

std::string Date::str() const {
    char buf[16];
    std::snprintf(buf, sizeof buf, "%04d-%02d-%02d", year_, month_, day_);
    return buf;
}

std::optional<TimeOfDay> TimeOfDay::parse(std::string_view text) {
    const std::string t = trim(text);
    if (t.size() != 5 || t[2] != ':') return std::nullopt;
    const auto h = parse_int(t.substr(0, 2), 0, 23);
    const auto m = parse_int(t.substr(3, 2), 0, 59);
    if (!h || !m) return std::nullopt;
    return TimeOfDay(int(*h * 60 + *m));
}

std::string TimeOfDay::str() const {
    char buf[16];
    std::snprintf(buf, sizeof buf, "%02d:%02d", minutes_ / 60, minutes_ % 60);
    return buf;
}

}  // namespace crm
